layout(std140) uniform CommonVariables {
	vec4 PositionFix;
	vec4 GlFogcolor;
	float GlFogdensity;
	float GlFogend;
	float GlFogscale;
	float AlphaRef;
	vec4 ClipPlanes[6];
};

layout(std140) uniform CommonVariables {
	vec4 PositionFix;
	vec4 GlFogcolor;
	float GlFogdensity;
	float GlFogend;
	float GlFogscale;
	float AlphaRef;
	vec4 ClipPlanes[6];
};

layout(std140) uniform CommonVariables {
	vec4 PositionFix;
	vec4 GlFogcolor;
	float GlFogdensity;
	float GlFogend;
	float GlFogscale;
	float AlphaRef;
	vec4 ClipPlanes[6];
};

layout(std140) uniform AsmPixelOnly {
	vec4 BumpEnvMatrix;
	float LuminanceScale;
	float LuminanceOffset;
};

layout(std140) uniform FixedPipelineVertexOnly {
	mat4 ModelViewMatrix;
	mat4 ProjectionMatrix;
	mat4 ModelViewProjectionMatrix;
	mat4 ViewTransform;
	vec4 ViewportSizes;
	mat3 NormalMatrix;
};

struct LightSource {
	vec4	ambient;
	vec4	diffuse;
	vec4	specular;
	vec4	position;
	vec3	spotDirection;
	float	spotExponent;
	float	spotCosCutoff;
	float	constantAttenuation;
	float	linearAttenuation;
	float	quadraticAttenuation;
};

struct MaterialInfo {
	vec4	emission;
	vec4	ambient;
	vec4	diffuse;
	vec4	specular;
	float	shininess;
};

layout(std140) uniform FixedPipelineVertexOnlyRare {
	mat4 TextureMatrix[%u];
	mat4 WorldTransforms[4];
	LightSource LightSources[%u];
	vec4 LightModelAmbient;
	MaterialInfo Material;
};

layout(std140) uniform FixedPipelinePixelOnly {
	vec4 TextureStageConstant[%d];
	vec4 TextureFactor;
	vec4 LuminanceScaleOffset[%d];
	vec4 BumpEnvMap[%d];
};

#version 150

// Fragment program for StretchRect() and other direct copying functions

uniform sampler2D CopySampler;
in vec2 eON_TexCoordV;
out vec4 FragColor;

void main()
{
	FragColor = clamp( texture( CopySampler, eON_TexCoordV.xy ), 0.0, 1.0 );
}

