// Fragment program for StretchRect() and other direct copying functions

uniform sampler2D CopySampler;
varying vec2 eON_TexCoordV;
void main()
{
	gl_FragColor = clamp( texture2D( CopySampler, eON_TexCoordV.xy), 0.0, 1.0 );
}

