#version 150

// Vertex program for StretchRect() and other direct copying functions

in vec3 eON_Position;
in vec2 eON_TexCoord;
out vec2 eON_TexCoordV;

void main()
{
	gl_Position = vec4( eON_Position, 1.0 );
	eON_TexCoordV.xy = eON_TexCoord.xy;
}

